const defaultLang='en';
const originalText=new WeakMap();
const langSelects=[...document.querySelectorAll('.lang-select')];
const drawer=document.getElementById('mobileDrawer');
const overlay=document.getElementById('drawerOverlay');
const menuToggle=document.querySelector('.menu-toggle');
const drawerClose=document.querySelector('.drawer-close');
const navLinks=[...document.querySelectorAll('.menu a')];
const drawerLinks=[...document.querySelectorAll('.drawer-links a')];
const allNavLinks=[...navLinks,...drawerLinks];

function setLanguage(lang){
  const dict=translations[lang]||{};
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  const nodes=[]; let n;
  while(n=walker.nextNode()) nodes.push(n);
  nodes.forEach(node=>{
    const key=originalText.get(node) || node.nodeValue.trim();
    if(!originalText.has(node)) originalText.set(node,key);
    const origKey=originalText.get(node);
    if(lang==='en'){
      if(node.nodeValue.trim()!==origKey){
        const lead=node.nodeValue.match(/^\s*/)?.[0]||'';
        const trail=node.nodeValue.match(/\s*$/)?.[0]||'';
        node.nodeValue=lead+origKey+trail;
      }
    } else if(dict[origKey]){
      const lead=node.nodeValue.match(/^\s*/)?.[0]||'';
      const trail=node.nodeValue.match(/\s*$/)?.[0]||'';
      node.nodeValue=lead+dict[origKey]+trail;
    }
  });
  document.documentElement.lang=lang;
  document.title=lang==='en'?'Duy Hoàng — Backend / Full-stack Engineer':`Duy Hoàng — ${dict['Backend / Full-stack Engineer']||'Backend / Full-stack Engineer'}`;
  langSelects.forEach(s=>s.value=lang);
  localStorage.setItem('duyPortfolioLang',lang);
}

function openDrawer(){drawer.classList.add('open');overlay.classList.add('open');document.body.classList.add('drawer-open');drawer.setAttribute('aria-hidden','false');menuToggle.setAttribute('aria-expanded','true');}
function closeDrawer(){drawer.classList.remove('open');overlay.classList.remove('open');document.body.classList.remove('drawer-open');drawer.setAttribute('aria-hidden','true');menuToggle.setAttribute('aria-expanded','false');}
menuToggle?.addEventListener('click',openDrawer);
drawerClose?.addEventListener('click',closeDrawer);
overlay?.addEventListener('click',closeDrawer);
langSelects.forEach(select=>select.addEventListener('change',e=>{setLanguage(e.target.value);}));
allNavLinks.forEach(link=>link.addEventListener('click',e=>{
  const target=document.querySelector(link.getAttribute('href'));
  if(target){e.preventDefault();closeDrawer();target.scrollIntoView({behavior:'smooth',block:'start'});history.replaceState(null,'',link.getAttribute('href'));}
}));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();});
const savedLang=localStorage.getItem('duyPortfolioLang')||defaultLang;
if(savedLang!=='en')setLanguage(savedLang); else langSelects.forEach(s=>s.value='en');

const activeLinks=[...document.querySelectorAll('.menu a, .drawer-links a')],sections=[...document.querySelectorAll('main section')];
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)activeLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}),{rootMargin:'-35% 0px -55% 0px'});
sections.forEach(s=>observer.observe(s));

// --- Dark / Light Theme Toggle ---
(function initTheme() {
  const saved = localStorage.getItem('duyPortfolioTheme');
  const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
  const theme = saved || (prefersDark ? 'dark' : 'dark');
  document.documentElement.setAttribute('data-theme', theme);
})();

function toggleTheme() {
  const html = document.documentElement;
  const current = html.getAttribute('data-theme') || 'dark';
  const next = current === 'dark' ? 'light' : 'dark';
  html.setAttribute('data-theme', next);
  localStorage.setItem('duyPortfolioTheme', next);
}

document.querySelector('.theme-toggle')?.addEventListener('click', toggleTheme);

